package cn.huankan.event;
import java.util.*;import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.ObjectMapper;
@Service public class AiEvaluationService {private final JdbcTemplate db;private final AiResearchService ai;private final ObjectMapper json;public AiEvaluationService(JdbcTemplate d,AiResearchService a,ObjectMapper j){db=d;ai=a;json=j;}@Transactional public Object prepare(){for(var r:db.queryForList("SELECT f.fields,p.evidence_id,f.event_id,r.raw_content,r.raw_content_hash FROM fact_candidate f JOIN fact_evidence p ON p.fact_id=f.id JOIN raw_evidence r ON r.id=p.evidence_id JOIN source_registry s ON s.id=r.source_id WHERE s.level='L0' ORDER BY CASE WHEN f.fact_type='MACRO_OBSERVATION' THEN 0 ELSE 1 END,f.created_at LIMIT 2")){if(!EvidenceService.hash((byte[])r.get("raw_content")).equals(r.get("raw_content_hash")))throw new IllegalArgumentException("AI评测输入证据哈希失败");for(String task:List.of("CHINESE_SUMMARY","INSTITUTION","MACRO_INDICATOR","AMOUNT_UNIT","LITERAL_QUOTE","POSITIVE_NEGATIVE","UNKNOWN_FIELDS","UNTRUSTED_CONTENT"))db.update("INSERT INTO ai_evaluation_case(id,evidence_id,event_id,task_type,expected_fields,evidence_hash,prompt_version) VALUES(?,?,?,?,?::jsonb,?,?) ON CONFLICT DO NOTHING",UUID.randomUUID(),r.get("evidence_id"),r.get("event_id"),task,r.get("fields").toString(),r.get("raw_content_hash"),AiResearchService.PROMPT_VERSION);}return status();}public Object status(){return Map.of("provider",ai.status(),"cases",db.queryForList("SELECT id,evidence_id,event_id,task_type,evidence_hash,prompt_version,created_at FROM ai_evaluation_case ORDER BY created_at,id LIMIT 50"),"state","准备样本不是模型运行；未配置模型时真实质量尚未验收","retry_policy","失败原样保留；付费调用不自动重试，需再次发起且重新通过预算门禁");}}
